export interface CheckpointClaim {
  /**
   * True iff THIS call was the one that atomically transitioned the
   * checkpoint away from its prior value (or first-established it — see
   * `previousTree`). False means some other caller — another overlapping
   * hook process, most likely — already advanced it to exactly this
   * `currentTree` first; the caller must treat that as "nothing new to
   * report" rather than re-deriving and re-processing the same diff.
   */
  claimed: boolean;
  /** The checkpoint value as of just before this claim. Null only when this is the very first observation of this (session, repo) pair. */
  previousTree: string | null;
}

/**
 * Atomically reads the current checkpoint for (sessionId, repo) and, only
 * if it differs from `currentTree`, advances it to `currentTree` — as ONE
 * SQLite transaction opened with BEGIN IMMEDIATE, which takes SQLite's
 * write lock immediately rather than lazily on first write. That's what
 * makes this safe across separate OS processes (each hook firing is its
 * own process with its own DB connection): a second, truly-concurrent
 * caller's own IMMEDIATE transaction blocks (via `busy_timeout`, see
 * `openStore`) until the first one commits, then reads the ALREADY-
 * ADVANCED value and correctly sees claimed=false.
 *
 * Fixes a real bug an independent test pass (Codex) reproduced: the
 * previous implementation read the checkpoint (`getCheckpointTree`) and
 * wrote it back (`setCheckpointTree`) as two separate statements with no
 * transaction tying them together, so several hook processes racing to
 * handle ONE edit could all read the same stale checkpoint before any of
 * them advanced it — each independently concluded "this is new" and each
 * ran (and paid for) its own generation call for what was actually a
 * single change. See DECISIONS.md's "Atomic checkpoint claim" entry.
 */
export function claimCheckpointAdvance(
  db: Database.Database,
  sessionId: string,
  repo: string,
  currentTree: string
): CheckpointClaim {
  const attempt = db.transaction((): CheckpointClaim => {
    const previousTree = getCheckpointTree(db, sessionId, repo);
    if (previousTree === currentTree) {
      return { claimed: false, previousTree };
    }
    setCheckpointTree(db, sessionId, repo, currentTree);
    return { claimed: true, previousTree };
  });
  return attempt.immediate();
}

/**
 * Atomically seeds the checkpoint for (sessionId, repo) to `currentTree`
 * ONLY if no checkpoint exists yet for that pair — a no-op (returns false)
 * if one was already established, by this call or a concurrent one. Same
 * IMMEDIATE-transaction reasoning as `claimCheckpointAdvance`: without it,
 * two hook processes racing to seed the very first observation of a
 * (session, repo) pair could both "win," which is harmless on its own
 * (both would write the same baseline value) but is fixed here anyway so
 * every checkpoint mutation in the codebase goes through one atomic path.
 */
export function claimCheckpointSeed(
  db: Database.Database,
  sessionId: string,
  repo: string,
  currentTree: string
): boolean {
  const attempt = db.transaction((): boolean => {
    if (getCheckpointTree(db, sessionId, repo) !== null) return false;
    setCheckpointTree(db, sessionId, repo, currentTree);
    return true;
  });
  return attempt.immediate();
}

